#!/usr/bin/env python3
"""Run the executable under a pty and print raw output with escapes visible and codepoints for non-ascii."""
import os, pty, sys, subprocess, re, select

def run(args, cwd=None, cols=80, env=None):
    import fcntl, termios, struct
    pid, fd = pty.fork()
    if pid == 0:
        if cwd: os.chdir(cwd)
        if env:
            os.environ.update(env)
        os.execv(args[0], args)
    # set window size
    winsz = struct.pack("HHHH", 24, cols, 0, 0)
    fcntl.ioctl(fd, termios.TIOCSWINSZ, winsz)
    out = b""
    while True:
        try:
            r = os.read(fd, 65536)
        except OSError:
            break
        if not r: break
        out += r
    os.waitpid(pid, 0)
    return out.decode("utf-8", "replace").replace("\r\n", "\n")

def show(s):
    res = []
    for ch in s:
        o = ord(ch)
        if ch == "\x1b":
            res.append("\\e")
        elif o > 126:
            res.append("<U+%04X>" % o)
        else:
            res.append(ch)
    return "".join(res)

if __name__ == "__main__":
    args = sys.argv[1:]
    cols = 80
    if args and args[0].startswith("--cols="):
        cols = int(args[0][7:]); args = args[1:]
    out = run(["/workspace/executable"] + args, cols=cols)
    print(show(out))
EOF
