//! Terminal related helpers.

use std::mem::MaybeUninit;

/// Get the width of the terminal attached to the given file descriptor.
fn width_of(fd: libc::c_int) -> Option<usize> {
	unsafe {
		if libc::isatty(fd) != 1 {
			return None;
		}
		let mut ws = MaybeUninit::<libc::winsize>::zeroed();
		if libc::ioctl(fd, libc::TIOCGWINSZ, ws.as_mut_ptr()) == -1 {
			return None;
		}
		let ws = ws.assume_init();
		if ws.ws_col == 0 {
			None
		} else {
			Some(ws.ws_col as usize)
		}
	}
}

/// Get the width of the terminal connected to standard output, if any.
pub fn stdout_width() -> Option<usize> {
	width_of(libc::STDOUT_FILENO)
}

/// Get the width of any terminal connected to the process, checking the
/// standard streams in order (stdout, stderr, stdin).
pub fn any_width() -> Option<usize> {
	[libc::STDOUT_FILENO, libc::STDERR_FILENO, libc::STDIN_FILENO]
		.into_iter()
		.find_map(width_of)
}

/// Determine the width to use for wrapping help text.
pub fn help_width() -> usize {
	if let Some(w) = any_width() {
		return w;
	}
	std::env::var("COLUMNS")
		.ok()
		.and_then(|v| v.parse::<usize>().ok())
		.unwrap_or(100)
}
EOF
