use serde::Deserialize;

/// A data point that can be shown about a node in the detail view.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum DetailField {
	Dev,
	Ino,
	Nlink,
	Typ,
	Perm,
	Oct,
	User,
	Uid,
	Group,
	Gid,
	Size,
	Blocks,
	Btime,
	Ctime,
	Mtime,
	Atime,
	Git,
	None,
	Std,
	All,
	Name,
}

impl DetailField {
	/// Values that can be passed on the command line, in order.
	pub const CLI_VALUES: &'static [(&'static str, DetailField)] = &[
		("dev", DetailField::Dev),
		("ino", DetailField::Ino),
		("nlink", DetailField::Nlink),
		("typ", DetailField::Typ),
		("perm", DetailField::Perm),
		("oct", DetailField::Oct),
		("user", DetailField::User),
		("uid", DetailField::Uid),
		("group", DetailField::Group),
		("gid", DetailField::Gid),
		("size", DetailField::Size),
		("blocks", DetailField::Blocks),
		("btime", DetailField::Btime),
		("ctime", DetailField::Ctime),
		("mtime", DetailField::Mtime),
		("atime", DetailField::Atime),
		("git", DetailField::Git),
		("none", DetailField::None),
		("std", DetailField::Std),
		("all", DetailField::All),
	];

	pub fn from_cli(s: &str) -> Option<Self> {
		Self::CLI_VALUES
			.iter()
			.find(|(name, _)| *name == s)
			.map(|(_, v)| *v)
	}

	/// The fields that make up the standard detail view.
	pub fn std_fields() -> Vec<Self> {
		vec![
			DetailField::Nlink,
			DetailField::Typ,
			DetailField::Perm,
			DetailField::User,
			DetailField::Group,
			DetailField::Size,
			DetailField::Mtime,
		]
	}

	/// All concrete fields.
	pub fn all_fields() -> Vec<Self> {
		vec![
			DetailField::Dev,
			DetailField::Ino,
			DetailField::Nlink,
			DetailField::Typ,
			DetailField::Perm,
			DetailField::Oct,
			DetailField::User,
			DetailField::Uid,
			DetailField::Group,
			DetailField::Gid,
			DetailField::Size,
			DetailField::Blocks,
			DetailField::Btime,
			DetailField::Ctime,
			DetailField::Mtime,
			DetailField::Atime,
			DetailField::Git,
		]
	}

	/// Expand the list given by the user into the concrete list of fields.
	///
	/// Every value before the last `none` is discarded, `std` and `all` are
	/// expanded and duplicates are removed, keeping the last occurrence.
	pub fn resolve(fields: &[Self]) -> Vec<Self> {
		let start = fields
			.iter()
			.rposition(|f| *f == DetailField::None)
