use colored::{Color, ColoredString, Colorize};

/// A set of styling directives that can be applied to text.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct Style {
	bold: bool,
	dimmed: bool,
	underline: bool,
	reversed: bool,
	italic: bool,
	blink: bool,
	hidden: bool,
	strikethrough: bool,
	fg: Option<Color>,
	bg: Option<Color>,
}

impl Style {
	/// Parse a whitespace separated list of directives into a style.
	pub fn parse(directives: &str) -> Self {
		Self::default().extend(directives)
	}

	/// Layer the given directives on top of this style.
	pub fn extend(&self, directives: &str) -> Self {
		let mut style = self.clone();
		for word in directives.split_whitespace() {
			match word {
				"bold" => style.bold = true,
				"dimmed" => style.dimmed = true,
				"underline" => style.underline = true,
				"reversed" => style.reversed = true,
				"italic" => style.italic = true,
				"blink" => style.blink = true,
				"hidden" => style.hidden = true,
				"strikethrough" => style.strikethrough = true,
				_ => {
					if let Some(color) = word.strip_prefix("bg:") {
						if let Some(c) = parse_color(color) {
							style.bg = Some(c);
						}
					} else if let Some(c) = parse_color(word) {
						style.fg = Some(c);
					}
				}
			}
		}
		style
	}

	/// Remove the directives that do not make sense for icons.
	pub fn without_text_decorations(&self) -> Self {
		let mut style = self.clone();
		style.italic = false;
		style.underline = false;
		style
	}

	/// Whether this style has no effect at all.
	pub fn is_plain(&self) -> bool {
		*self == Self::default()
	}

	/// Apply this style to the given text, producing a string with ANSI
	/// escape sequences.
	pub fn apply(&self, text: &str) -> String {
		if self.hidden {
			return String::new();
		}
		if self.is_plain() {
			return text.to_string();
		}
		let mut cs: ColoredString = text.normal();
		if self.bold {
			cs = cs.bold();
		}
		if self.dimmed {
			cs = cs.dimmed();
		}
		if self.underline {
			cs = cs.underline();
		}
		if self.reversed {
			cs = cs.reversed();
		}
		if self.italic {
			cs = cs.italic();
		}
		if self.blink {
			cs = cs.blink();
		}
		if self.strikethrough {
			cs = cs.strikethrough();
		}
		if let Some(fg) = self.fg {
			cs = cs.color(fg);
		}
		if let Some(bg) = self.bg {
			cs = cs.on_color(bg);
		}
		cs.to_string()
	}
}

/// Parse a single color directive.
fn parse_color(word: &str) -> Option<Color> {
	let color = match word {
		"black" => Color::Black,
		"red" => Color::Red,
		"green" => Color::Green,
		"yellow" => Color::Yellow,
		"blue" => Color::Blue,
		"magenta" | "purple" => Color::Magenta,
		"cyan" => Color::Cyan,
		"white" => Color::White,
		"bright_black" => Color::BrightBlack,
		"bright_red" => Color::BrightRed,
		"bright_green" => Color::BrightGreen,
		"bright_yellow" => Color::BrightYellow,
		"bright_blue" => Color::BrightBlue,
		"bright_magenta" | "bright_purple" => Color::BrightMagenta,
		"bright_cyan" => Color::BrightCyan,
		"bright_white" => Color::BrightWhite,
		_ => {
			if let Some(hex) = word.strip_prefix('#') {
				return parse_hex(hex);
			}
			if let Some(rest) = word.strip_prefix("rgb(") {
				let inner = rest.strip_suffix(')')?;
				let parts: Vec<&str> = inner.split(',').map(|p| p.trim()).collect();
				if parts.len() != 3 {
					return None;
				}
				let r = parts[0].parse::<u8>().ok()?;
				let g = parts[1].parse::<u8>().ok()?;
				let b = parts[2].parse::<u8>().ok()?;
				return Some(Color::TrueColor { r, g, b });
			}
			return None;
		}
	};
	Some(color)
}

/// Parse a hex color code of the form `rrggbb`.
fn parse_hex(hex: &str) -> Option<Color> {
	if hex.len() != 6 {
		return None;
	}
	let r = u8::from_str_radix(&hex[0..2], 16).ok()?;
	let g = u8::from_str_radix(&hex[2..4], 16).ok()?;
	let b = u8::from_str_radix(&hex[4..6], 16).ok()?;
	Some(Color::TrueColor { r, g, b })
}
