//! A generic representation of configuration data.

use std::collections::BTreeMap;
use std::fmt;
use std::sync::Arc;

use serde::de::{self, Deserialize, Deserializer, EnumAccess, MapAccess, SeqAccess, VariantAccess, Visitor};

/// A numeric value, keeping track of how it was written.
#[derive(Debug, Clone, PartialEq)]
pub enum Num {
	I64(i64),
	U64(u64),
	I128(i128),
	U128(u128),
	F64(f64),
}

/// The payload of a configuration value.
#[derive(Debug, Clone, PartialEq)]
pub enum Data {
	Unit,
	Bool(bool),
	Num(Num),
	Str(String),
	Seq(Vec<Value>),
	Map(BTreeMap<String, Value>),
}

/// A configuration value along with the source it was read from.
#[derive(Debug, Clone, PartialEq)]
pub struct Value {
	pub tag: Option<Arc<String>>,
	pub data: Data,
}

impl Value {
	pub fn new(data: Data) -> Self {
		Self { tag: None, data }
	}

	/// Recursively tag this value and all nested values with the given source.
	pub fn tag_all(&mut self, tag: &Arc<String>) {
		self.tag = Some(tag.clone());
		match &mut self.data {
			Data::Seq(items) => items.iter_mut().for_each(|v| v.tag_all(tag)),
			Data::Map(map) => map.values_mut().for_each(|v| v.tag_all(tag)),
			_ => {}
		}
	}

	/// Merge `other` into this value.
	///
	/// Maps are merged recursively, sequences are concatenated and all other
	/// values are replaced by the newer value.
	pub fn admerge(self, other: Value) -> Value {
		match (self.data, other.data) {
			(Data::Map(mut a), Data::Map(b)) => {
				for (k, v) in b {
					let merged = match a.remove(&k) {
						Some(existing) => existing.admerge(v),
						None => v,
					};
					a.insert(k, merged);
				}
				Value {
					tag: self.tag,
					data: Data::Map(a),
				}
			}
			(Data::Seq(mut a), Data::Seq(b)) => {
				a.extend(b);
				Value {
					tag: self.tag,
					data: Data::Seq(a),
				}
			}
			(_, data) => Value {
				tag: other.tag,
				data,
			},
		}
	}
}

struct ValueVisitor;

impl<'de> Visitor<'de> for ValueVisitor {
	type Value = Value;

	fn expecting(&self, formatter: &mut fmt::Formatter) -> fmt::Result {
		formatter.write_str("any valid configuration value")
	}

	fn visit_bool<E: de::Error>(self, v: bool) -> Result<Value, E> {
		Ok(Value::new(Data::Bool(v)))
	}

	fn visit_i64<E: de::Error>(self, v: i64) -> Result<Value, E> {
		Ok(Value::new(Data::Num(Num::I64(v))))
	}

	fn visit_u64<E: de::Error>(self, v: u64) -> Result<Value, E> {
		Ok(Value::new(Data::Num(Num::U64(v))))
	}

	fn visit_i128<E: de::Error>(self, v: i128) -> Result<Value, E> {
		Ok(Value::new(Data::Num(Num::I128(v))))
	}

	fn visit_u128<E: de::Error>(self, v: u128) -> Result<Value, E> {
		Ok(Value::new(Data::Num(Num::U128(v))))
	}

	fn visit_f64<E: de::Error>(self, v: f64) -> Result<Value, E> {
		Ok(Value::new(Data::Num(Num::F64(v))))
	}

	fn visit_str<E: de::Error>(self, v: &str) -> Result<Value, E> {
		Ok(Value::new(Data::Str(v.to_string())))
	}

	fn visit_string<E: de::Error>(self, v: String) -> Result<Value, E> {
		Ok(Value::new(Data::Str(v)))
	}

	fn visit_unit<E: de::Error>(self) -> Result<Value, E> {
		Ok(Value::new(Data::Unit))
	}

	fn visit_none<E: de::Error>(self) -> Result<Value, E> {
		Ok(Value::new(Data::Unit))
	}

	fn visit_some<D: Deserializer<'de>>(self, deserializer: D) -> Result<Value, D::Error> {
		Deserialize::deserialize(deserializer)
	}

	fn visit_seq<A: SeqAccess<'de>>(self, mut seq: A) -> Result<Value, A::Error> {
		let mut items = vec![];
		while let Some(item) = seq.next_element()? {
			items.push(item);
		}
		Ok(Value::new(Data::Seq(items)))
	}

	fn visit_map<A: MapAccess<'de>>(self, mut map: A) -> Result<Value, A::Error> {
		let mut dict = BTreeMap::new();
		while let Some(key) = map.next_key::<String>()? {
			let value: Value = map.next_value()?;
			dict.insert(key, value);
		}
		Ok(Value::new(Data::Map(dict)))
	}

	fn visit_enum<A: EnumAccess<'de>>(self, data: A) -> Result<Value, A::Error> {
		let (tag, variant): (String, _) = data.variant()?;
		let value: Value = variant.newtype_variant()?;
		let mut dict = BTreeMap::new();
		dict.insert(tag, value);
		Ok(Value::new(Data::Map(dict)))
	}
}

