//! Path related helpers.

use std::path::{Component, Path, PathBuf};

/// Express `path` relative to `base`, both of which should be absolute.
///
/// Returns `None` when the relation cannot be expressed.
pub fn diff_paths(path: &Path, base: &Path) -> Option<PathBuf> {
	if path.is_absolute() != base.is_absolute() {
		return if path.is_absolute() {
			Some(path.to_path_buf())
		} else {
			None
		};
	}
	let mut ita = path.components();
	let mut itb = base.components();
	let mut comps: Vec<Component> = vec![];
	loop {
		match (ita.next(), itb.next()) {
			(None, None) => break,
			(Some(a), None) => {
				comps.push(a);
				comps.extend(ita.by_ref());
				break;
			}
			(None, _) => comps.push(Component::ParentDir),
			(Some(a), Some(b)) if comps.is_empty() && a == b => (),
			(Some(a), Some(Component::CurDir)) => comps.push(a),
			(Some(_), Some(Component::ParentDir)) => return None,
			(Some(a), Some(_)) => {
				comps.push(Component::ParentDir);
				for _ in itb {
					comps.push(Component::ParentDir);
				}
				comps.push(a);
				comps.extend(ita.by_ref());
				break;
			}
		}
	}
	Some(comps.iter().map(|c| c.as_os_str()).collect())
}

/// Describe a path relative to the current working directory, the way it is
/// shown in error messages.
pub fn display_relative(path: &Path) -> String {
	let abs = if path.is_absolute() {
		path.to_path_buf()
	} else {
		match std::env::current_dir() {
			Ok(cwd) => cwd.join(path),
			Err(_) => path.to_path_buf(),
		}
	};
	match std::env::current_dir()
		.ok()
		.and_then(|cwd| diff_paths(&abs, &cwd))
	{
		Some(rel) => rel.display().to_string(),
		None => abs.display().to_string(),
	}
}

/// The home directory of the current user.
pub fn home_dir() -> Option<PathBuf> {
	std::env::var_os("HOME")
		.filter(|h| !h.is_empty())
		.map(PathBuf::from)
		.or_else(|| unsafe {
			let pw = libc::getpwuid(libc::getuid());
			if pw.is_null() || (*pw).pw_dir.is_null() {
				return None;
			}
			let dir = std::ffi::CStr::from_ptr((*pw).pw_dir);
			let dir = dir.to_string_lossy().into_owned();
			if dir.is_empty() {
				None
			} else {
				Some(PathBuf::from(dir))
			}
		})
}
