//! Discovery, parsing and merging of configuration files.

use std::collections::BTreeMap;
use std::os::unix::fs::MetadataExt;
use std::path::{Path, PathBuf};
use std::sync::Arc;

use serde::Deserialize;

use super::conf::{Conf, DEFAULT_YAML};
use super::de::ValueDe;
use super::error::{ConfError, ConfErrorKind};
use super::value::{Data, Value};
use crate::utils::paths::{display_relative, home_dir};

const CONF_FILE_NAME: &str = ".pls.yml";

/// Load the configuration applicable to the given path.
///
/// `is_dir` tells whether the path refers to a directory; for other nodes the
/// configuration of the parent directory applies.
pub fn load_conf(path: &Path, is_dir: bool) -> Result<Conf, ConfError> {
	let mut merged = parse_yaml(DEFAULT_YAML, None)?;
	for conf_path in conf_paths(path, is_dir) {
		if !conf_path.is_file() {
			continue;
		}
		let source = Arc::new(display_relative(&conf_path));
		let contents = std::fs::read_to_string(&conf_path).map_err(|e| {
			ConfError::new(ConfErrorKind::Message(e.to_string())).with_source(source.to_string())
		})?;
		let value = parse_yaml(&contents, Some(&source))?;
		merged = merged.admerge(value);
	}
	Conf::deserialize(ValueDe::new(&merged))
}

/// Parse a YAML document into a value tree, tagging every value with the given
/// source.
fn parse_yaml(contents: &str, source: Option<&Arc<String>>) -> Result<Value, ConfError> {
	let dict: BTreeMap<String, Value> = serde_yaml::from_str(contents).map_err(|e| {
		let err = ConfError::new(ConfErrorKind::Message(e.to_string()));
		match source {
			Some(s) => err.with_source(s.to_string()),
			None => err,
		}
	})?;
	let mut value = Value::new(Data::Map(dict));
	if let Some(source) = source {
		value.tag_all(source);
	}
	Ok(value)
}

/// Determine the configuration files that apply to the given path, in the
/// order in which they should be merged (least specific first).
fn conf_paths(path: &Path, is_dir: bool) -> Vec<PathBuf> {
	let mut paths = vec![];
	if let Some(home) = home_dir() {
		paths.push(home.join(CONF_FILE_NAME));
	}
	if let Some(env) = std::env::var_os("PLS_CONFIG") {
		if !env.is_empty() {
			paths.push(PathBuf::from(env));
		}
	}

	let start: PathBuf = if is_dir {
		path.to_path_buf()
	} else {
		path.parent().map(Path::to_path_buf).unwrap_or_default()
	};
	let root = discover_repo(&start);

	let mut chain = vec![];
	for ancestor in start.ancestors() {
		chain.push(ancestor.join(CONF_FILE_NAME));
		match &root {
			Some(root) if ancestor != root.as_path() => continue,
			_ => break,
		}
	}
	chain.reverse();
	paths.extend(chain);
	paths
}

/// Find the working directory of the Git repository containing `start`.
fn discover_repo(start: &Path) -> Option<PathBuf> {
	let start = if start.as_os_str().is_empty() {
		Path::new(".")
	} else {
		start
	};
	let mut dir = std::fs::canonicalize(start).ok()?;
	loop {
		let dot_git = dir.join(".git");
		if let Ok(meta) = std::fs::symlink_metadata(&dot_git) {
			let git_dir = if meta.is_dir() {
				Some(dot_git.clone())
			} else if meta.is_file() {
				read_gitfile(&dot_git)
			} else {
				None
			};
			if let Some(git_dir) = git_dir {
				if is_git_dir(&git_dir) && owned_by_current_user(&git_dir) {
					return Some(dir);
				}
			}
		}
		if !dir.pop() {
			return None;
		}
	}
}

/// Resolve a `.git` file pointing to the actual repository directory.
fn read_gitfile(path: &Path) -> Option<PathBuf> {
	let contents = std::fs::read_to_string(path).ok()?;
	let target = contents.trim_end().strip_prefix("gitdir:")?.trim();
	if target.is_empty() {
		return None;
	}
	let target = Path::new(target);
	let resolved = if target.is_absolute() {
		target.to_path_buf()
	} else {
		path.parent()?.join(target)
	};
	std::fs::canonicalize(resolved).ok()
}

/// Whether the given directory looks like a Git repository directory.
fn is_git_dir(path: &Path) -> bool {
	path.join("HEAD").is_file() && path.join("objects").is_dir() && path.join("refs").is_dir()
}

/// Whether the given path is owned by the user running the program.
fn owned_by_current_user(path: &Path) -> bool {
	match std::fs::metadata(path) {
		Ok(meta) => meta.uid() == unsafe { libc::geteuid() },
		Err(_) => false,
	}
}
