				let d: Duration = e.duration();
				if d.subsec_nanos() == 0 {
					(-(d.as_secs() as i64), 0)
				} else {
					(-(d.as_secs() as i64) - 1, 1_000_000_000 - d.subsec_nanos())
				}
			}
		};
		let offset = local_offset(secs);
		let local = secs + offset;
		let days = local.div_euclid(86_400);
		let rem = local.rem_euclid(86_400);
		let (year, month, day) = civil_from_days(days);
		let ordinal = ordinal(year, month, day);
		// 1970-01-01 was a Thursday (index 3 with Monday as 0).
		let weekday = (days + 3).rem_euclid(7) as u32;
		Self {
			year,
			month,
			day,
			hour: (rem / 3600) as u32,
			minute: ((rem % 3600) / 60) as u32,
			second: (rem % 60) as u32,
			nanos,
			ordinal,
			weekday,
			offset,
		}
	}
}

/// Determine the local UTC offset (in seconds) for the given timestamp.
fn local_offset(secs: i64) -> i64 {
	unsafe {
		let t: libc::time_t = secs as libc::time_t;
		let mut tm: libc::tm = std::mem::zeroed();
		if libc::localtime_r(&t, &mut tm).is_null() {
			0
		} else {
			tm.tm_gmtoff as i64
		}
	}
}

/// Convert days since the Unix epoch into a civil date.
fn civil_from_days(z: i64) -> (i64, u32, u32) {
	let z = z + 719_468;
	let era = z.div_euclid(146_097);
	let doe = z.rem_euclid(146_097);
	let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
	let y = yoe + era * 400;
	let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
	let mp = (5 * doy + 2) / 153;
	let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
	let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
	(if m <= 2 { y + 1 } else { y }, m, d)
}

fn is_leap(year: i64) -> bool {
	(year % 4 == 0 && year % 100 != 0) || year % 400 == 0
}

fn ordinal(year: i64, month: u32, day: u32) -> u32 {
	const CUMULATIVE: [u32; 12] = [0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334];
	let mut ord = CUMULATIVE[(month - 1) as usize] + day;
	if month > 2 && is_leap(year) {
		ord += 1;
	}
	ord
}

#[derive(Debug, Clone, Copy, PartialEq)]
enum Padding {
	Zero,
	Space,
	None,
}

fn pad(value: impl std::fmt::Display, width: usize, padding: Padding) -> String {
	let s = value.to_string();
	match padding {
		Padding::Zero => format!("{s:0>width$}"),
		Padding::Space => format!("{s:>width$}"),
		Padding::None => s,
	}
}

/// Format a component such as `year` or `month repr:short`.
fn format_component(spec: &str, dt: &DateTime) -> Option<String> {
	let mut parts = spec.split_whitespace();
	let name = parts.next()?;
	let mut repr: Option<&str> = None;
	let mut case: Option<&str> = None;
	let mut padding = Padding::Zero;
	let mut digits: Option<usize> = None;
	let mut one_indexed = true;
	let mut sign_mandatory = false;
	for modifier in parts {
		let (key, value) = modifier.split_once(':')?;
		match key {
			"repr" => repr = Some(value),
			"case" => case = Some(value),
			"padding" => {
				padding = match value {
					"zero" => Padding::Zero,
					"space" => Padding::Space,
					"none" => Padding::None,
					_ => return None,
				}
			}
			"digits" => {
				digits = match value {
					"1+" => None,
					d => Some(d.parse().ok()?),
				}
			}
			"one_indexed" => one_indexed = value == "true",
			"sign" => sign_mandatory = value == "mandatory",
			_ => return None,
		}
	}
	let out = match name {
		"year" => {
			let year = dt.year;
			match repr.unwrap_or("full") {
				"full" => {
					let mut s = pad(year.abs(), 4, padding);
					if year < 0 {
						s.insert(0, '-');
					} else if sign_mandatory || year >= 10_000 {
						s.insert(0, '+');
					}
					s
				}
				"last_two" => pad(year.rem_euclid(100), 2, padding),
				"century" => {
					let mut s = pad((year / 100).abs(), 2, padding);
					if year < 0 {
						s.insert(0, '-');
					} else if sign_mandatory {
						s.insert(0, '+');
					}
					s
				}
				_ => return None,
			}
		}
		"month" => match repr.unwrap_or("numerical") {
			"numerical" => pad(dt.month, 2, padding),
			"short" => MONTHS_SHORT[(dt.month - 1) as usize].to_string(),
			"long" => MONTHS_LONG[(dt.month - 1) as usize].to_string(),
			_ => return None,
		},
		"day" => pad(dt.day, 2, padding),
		"ordinal" => pad(dt.ordinal, 3, padding),
		"weekday" => match repr.unwrap_or("long") {
			"long" => WEEKDAYS_LONG[dt.weekday as usize].to_string(),
			"short" => WEEKDAYS_SHORT[dt.weekday as usize].to_string(),
			"sunday" => {
				let n = (dt.weekday + 1) % 7;
				pad(if one_indexed { n + 1 } else { n }, 1, padding)
			}
			"monday" => {
				let n = dt.weekday;
				pad(if one_indexed { n + 1 } else { n }, 1, padding)
			}
			_ => return None,
		},
		"hour" => match repr.unwrap_or("24") {
			"24" => pad(dt.hour, 2, padding),
			"12" => {
				let h = dt.hour % 12;
				pad(if h == 0 { 12 } else { h }, 2, padding)
			}
			_ => return None,
		},
		"minute" => pad(dt.minute, 2, padding),
		"second" => pad(dt.second, 2, padding),
		"period" => {
			let upper = match case.unwrap_or("upper") {
				"upper" => true,
				"lower" => false,
				_ => return None,
			};
			let p = if dt.hour < 12 { "AM" } else { "PM" };
			if upper {
				p.to_string()
			} else {
				p.to_lowercase()
			}
		}
		"subsecond" => {
			let nanos = format!("{:09}", dt.nanos);
			match digits {
				Some(d) if d <= 9 => nanos[..d].to_string(),
				Some(_) => return None,
				None => {
					let trimmed = nanos.trim_end_matches('0');
					if trimmed.is_empty() {
						"0".to_string()
					} else {
						trimmed.to_string()
					}
				}
			}
		}
		"offset_hour" => {
			let hours = (dt.offset / 3600).abs();
			let mut s = pad(hours, 2, padding);
			if dt.offset < 0 {
				s.insert(0, '-');
			} else if sign_mandatory {
				s.insert(0, '+');
			}
			s
		}
		"offset_minute" => pad(((dt.offset % 3600) / 60).abs(), 2, padding),
		"offset_second" => pad((dt.offset % 60).abs(), 2, padding),
		"unix_timestamp" => {
			let secs = unix_seconds(dt);
			match repr.unwrap_or("second") {
				"second" => secs.to_string(),
				"millisecond" => (secs * 1000 + dt.nanos as i64 / 1_000_000).to_string(),
				"microsecond" => (secs * 1_000_000 + dt.nanos as i64 / 1_000).to_string(),
				"nanosecond" => (secs * 1_000_000_000 + dt.nanos as i64).to_string(),
				_ => return None,
			}
		}
		_ => return None,
	};
	Some(out)
}

fn unix_seconds(dt: &DateTime) -> i64 {
	let y = if dt.month <= 2 { dt.year - 1 } else { dt.year };
	let era = y.div_euclid(400);
	let yoe = y.rem_euclid(400);
	let m = dt.month as i64;
	let doy = (153 * (if m > 2 { m - 3 } else { m + 9 }) + 2) / 5 + dt.day as i64 - 1;
	let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
	let days = era * 146_097 + doe - 719_468;
	days * 86_400 + dt.hour as i64 * 3600 + dt.minute as i64 * 60 + dt.second as i64 - dt.offset
}

/// Format a timestamp according to the given format description.
///
/// Text outside of brackets is copied verbatim, `[[` produces a literal `[`.
/// Unknown components are rendered as given.
pub fn format_time(time: SystemTime, description: &str) -> String {
	let dt = DateTime::from_system_time(time);
	let mut out = String::new();
	let mut chars = description.chars().peekable();
	while let Some(ch) = chars.next() {
		if ch != '[' {
			out.push(ch);
			continue;
		}
		if chars.peek() == Some(&'[') {
			chars.next();
			out.push('[');
			continue;
		}
		let mut spec = String::new();
		let mut closed = false;
		for c in chars.by_ref() {
			if c == ']' {
				closed = true;
				break;
			}
			spec.push(c);
		}
		if !closed {
			out.push('[');
			out.push_str(&spec);
			break;
		}
		match format_component(spec.trim(), &dt) {
			Some(s) => out.push_str(&s),
			None => {
				out.push('[');
				out.push_str(&spec);
				out.push(']');
			}
		}
	}
	out
}
