//! Lookup of user and group names.

use std::ffi::CStr;

/// The name of the user with the given ID, falling back to the ID itself.
pub fn user_name(uid: u32) -> String {
	unsafe {
		let pw = libc::getpwuid(uid);
		if pw.is_null() || (*pw).pw_name.is_null() {
			return uid.to_string();
		}
		CStr::from_ptr((*pw).pw_name)
			.to_string_lossy()
			.into_owned()
	}
}

/// The name of the group with the given ID, falling back to the ID itself.
pub fn group_name(gid: u32) -> String {
	unsafe {
		let gr = libc::getgrgid(gid);
		if gr.is_null() || (*gr).gr_name.is_null() {
			return gid.to_string();
		}
		CStr::from_ptr((*gr).gr_name)
			.to_string_lossy()
			.into_owned()
	}
}

/// The ID of the user running the program.
pub fn current_uid() -> u32 {
	unsafe { libc::getuid() }
}

/// Whether the user running the program is listed as a member of the group
/// with the given ID.
pub fn current_user_in_group(gid: u32) -> bool {
	let user = user_name(current_uid());
	unsafe {
		let gr = libc::getgrgid(gid);
		if gr.is_null() || (*gr).gr_mem.is_null() {
			return false;
		}
		let mut members = (*gr).gr_mem;
		while !(*members).is_null() {
			let member = CStr::from_ptr(*members).to_string_lossy();
			if member == user {
				return true;
			}
			members = members.add(1);
		}
	}
	false
}
