//! Rendering of file permissions.

use crate::config::Conf;
use crate::enums::{Oct, Sym};
use crate::fmt::wrap;

/// Render the symbolic permission string, e.g. `rwx r-x r-x`, as markup.
pub fn perm_markup(mode: u32, conf: &Conf) -> String {
	let triplets = [
		(0o400, 0o200, 0o100, 0o4000, 's'),
		(0o040, 0o020, 0o010, 0o2000, 's'),
		(0o004, 0o002, 0o001, 0o1000, 't'),
	];
	let mut parts = vec![];
	for (r, w, x, special, special_ch) in triplets {
		let mut triplet = String::new();
		triplet.push_str(&sym(mode & r != 0, 'r', Sym::Read, conf));
		triplet.push_str(&sym(mode & w != 0, 'w', Sym::Write, conf));
		let has_x = mode & x != 0;
		if mode & special != 0 {
			let ch = if has_x {
				special_ch
			} else {
				special_ch.to_ascii_uppercase()
			};
			triplet.push_str(&wrap(conf.perm_style(Sym::Special), &ch.to_string()));
		} else {
			triplet.push_str(&sym(has_x, 'x', Sym::Execute, conf));
		}
		parts.push(triplet);
	}
	parts.join(" ")
}

fn sym(set: bool, ch: char, kind: Sym, conf: &Conf) -> String {
	if set {
		wrap(conf.perm_style(kind), &ch.to_string())
	} else {
		wrap(conf.perm_style(Sym::None), "-")
	}
}

/// Render the octal permission string, e.g. `755` or `4755`, as markup.
pub fn oct_markup(mode: u32, conf: &Conf) -> String {
	let special = (mode >> 9) & 0o7;
	let user = (mode >> 6) & 0o7;
	let group = (mode >> 3) & 0o7;
	let other = mode & 0o7;
	let mut out = String::new();
	if special != 0 {
		out.push_str(&wrap(conf.oct_style(Oct::Special), &special.to_string()));
	}
	out.push_str(&wrap(conf.oct_style(Oct::User), &user.to_string()));
	out.push_str(&wrap(conf.oct_style(Oct::Group), &group.to_string()));
	out.push_str(&wrap(conf.oct_style(Oct::Other), &other.to_string()));
	out
}
