//! Resolution and rendering of symlink targets.

use std::path::{Path, PathBuf};
use std::rc::Rc;

use crate::config::Conf;
use crate::enums::{SymState, Typ};
use crate::fmt::{escape, wrap};
use crate::models::Node;

/// The resolved target of a symlink.
#[derive(Debug)]
pub enum SymTarget {
	/// The target exists; the node describes it.
	Ok(Box<Node>),
	/// The target does not exist.
	Broken(String),
	/// Following the target leads back to itself.
	Cyclic(String),
	/// The target could not be examined.
	Error(std::io::Error),
}

impl SymTarget {
	/// Resolve the target of the symlink at the given path.
	pub fn resolve(path: &Path, conf: &Rc<Conf>) -> Self {
		let target = match std::fs::read_link(path) {
			Ok(target) => target,
			Err(e) => return SymTarget::Error(e),
		};
		let target_str = target.to_string_lossy().into_owned();
		let abs_target: PathBuf = if target.is_absolute() {
			target.clone()
		} else {
			match path.parent() {
				Some(parent) => parent.join(&target),
				None => target.clone(),
			}
		};
		match std::fs::metadata(&abs_target) {
			Err(e) if e.kind() == std::io::ErrorKind::NotFound => SymTarget::Broken(target_str),
			Err(e) if e.raw_os_error() == Some(libc::ELOOP) => SymTarget::Cyclic(target_str),
			Err(e) => SymTarget::Error(e),
			Ok(_) => match std::fs::symlink_metadata(&abs_target) {
				Ok(meta) => {
					let node = Node::for_target(target_str, abs_target, meta, conf.clone());
					SymTarget::Ok(Box::new(node))
				}
				Err(e) => SymTarget::Error(e),
			},
		}
	}

	pub fn state(&self) -> SymState {
		match self {
			SymTarget::Ok(_) => SymState::Ok,
			SymTarget::Broken(_) => SymState::Broken,
			SymTarget::Cyclic(_) => SymState::Cyclic,
			SymTarget::Error(_) => SymState::Error,
		}
	}

	/// Render the target as markup, to be shown after the symlink's name.
	pub fn markup(&self, conf: &Conf) -> String {
		let info = conf.symlink_info(self.state());
		match self {
			SymTarget::Ok(node) => {
				let typ_style = conf.typ_info(node.typ).style;
				let mut inner = wrap(&typ_style, &escape(&node.name));
				if node.typ == Typ::Symlink {
					let target = SymTarget::resolve(&node.path, &node.conf);
					inner.push(' ');
					inner.push_str(&target.markup(conf));
				}
				format!(
					"{} {}",
					wrap(&info.style, &info.sep),
					wrap(&info.ref_style, &inner)
				)
			}
			SymTarget::Broken(path) | SymTarget::Cyclic(path) => wrap(
				&info.style,
				&format!("{} {}", info.sep, wrap(&info.ref_style, &escape(path))),
			),
			SymTarget::Error(err) => wrap(
				&info.style,
				&format!("{} <bold red>error:</> {}", info.sep, escape(&err.to_string())),
			),
		}
	}
}
