//! A node is a single file system entry along with everything needed to
//! display it.

use std::fs::Metadata;
use std::os::unix::fs::{MetadataExt, PermissionsExt};
use std::path::{Path, PathBuf};
use std::rc::Rc;
use std::time::SystemTime;

use crate::args::Args;
use crate::config::Conf;
use crate::enums::{Collapse, DetailField, Typ};
use crate::fmt::wrap;
use crate::models::owner;
use crate::models::perm::{oct_markup, perm_markup};
use crate::models::symlink::SymTarget;
use crate::utils::size::format_size;
use crate::utils::time::format_time;

#[derive(Debug)]
pub struct Node {
	/// The name shown in the output.
	pub name: String,
	/// The full path to the node.
	pub path: PathBuf,
	/// Metadata obtained without following symlinks.
	pub meta: Metadata,
	pub typ: Typ,
	pub conf: Rc<Conf>,
	/// Style directives contributed by the matching specs.
	pub spec_style: String,
	pub importance: i8,
	/// The glyph to show before the name, if any.
	pub icon: Option<String>,
	pub collapse: Option<Collapse>,
	/// Whether the node was given on the command line (as opposed to being
	/// read from a directory).
	pub is_arg: bool,
	pub children: Vec<Node>,
}

impl Node {
	/// Create a node for an entry inside a directory.
	pub fn new(name: String, path: PathBuf, meta: Metadata, conf: Rc<Conf>, is_arg: bool) -> Self {
		let typ = Typ::from_file_type(&meta.file_type());
		let match_name = path
			.file_name()
			.map(|n| n.to_string_lossy().into_owned())
			.unwrap_or_else(|| name.clone());
		let mut node = Self {
			name,
			path,
			meta,
			typ,
			conf,
			spec_style: String::new(),
			importance: 0,
			icon: None,
			collapse: None,
			is_arg,
			children: vec![],
		};
		node.apply_specs(&match_name);
		node
	}

	/// Create a node describing the target of a symlink.
	pub fn for_target(name: String, path: PathBuf, meta: Metadata, conf: Rc<Conf>) -> Self {
		let typ = Typ::from_file_type(&meta.file_type());
		Self {
			name,
			path,
			meta,
			typ,
			conf,
			spec_style: String::new(),
			importance: 0,
			icon: None,
			collapse: None,
			is_arg: true,
			children: vec![],
		}
	}

	/// Compute the attributes contributed by the matching specs.
	fn apply_specs(&mut self, match_name: &str) {
		let conf = self.conf.clone();
		let mut icon_names: Vec<&str> = vec![];
		for spec in &conf.specs {
			if !spec.pattern.is_match(match_name) {
				continue;
			}
			if let Some(style) = &spec.style {
				self.spec_style = style.clone();
			}
			if let Some(imp) = spec.importance {
				self.importance = imp;
			}
			if let Some(collapse) = &spec.collapse {
				self.collapse = Some(collapse.clone());
			}
			// Later specs take precedence, so their icons are tried first.
			let mut names: Vec<&str> = spec.icons.iter().map(|s| s.as_str()).collect();
			names.extend(icon_names);
			icon_names = names;
		}
		let typ_info = conf.typ_info(self.typ);
		icon_names.extend(typ_info.icons.iter().map(|s| s.as_str()));
		self.icon = icon_names
			.iter()
			.find_map(|name| conf.icons.get(*name))
			.cloned();
	}

	// ===== Sorting keys =====

	/// Directories come before everything else.
	pub fn category(&self) -> u8 {
		if self.typ == Typ::Dir {
			0
		} else {
			1
		}
	}

	pub fn user_name(&self) -> String {
		owner::user_name(self.meta.uid())
	}

	pub fn group_name(&self) -> String {
		owner::group_name(self.meta.gid())
	}

	/// The canonical name: lowercased with leading punctuation removed.
	pub fn cname(&self) -> String {
		self.name
			.to_lowercase()
			.trim_start_matches(|c: char| !c.is_alphanumeric())
			.to_string()
	}

	pub fn ext(&self) -> String {
		Path::new(&self.name)
			.extension()
			.map(|e| e.to_string_lossy().into_owned())
			.unwrap_or_default()
	}

	pub fn time(&self, field: DetailField) -> Option<SystemTime> {
		match field {
			DetailField::Btime => self.meta.created().ok(),
			DetailField::Ctime => Some(
				SystemTime::UNIX_EPOCH
					+ std::time::Duration::new(
						self.meta.ctime().max(0) as u64,
						self.meta.ctime_nsec() as u32,
					),
			),
			DetailField::Mtime => self.meta.modified().ok(),
			DetailField::Atime => self.meta.accessed().ok(),
			_ => None,
		}
	}

	// ===== Filtering =====

	/// The importance of the node relative to the cutoff.
	pub fn rel_importance(&self, args: &Args) -> i8 {
		self.importance.saturating_sub(args.imp)
	}

	/// Whether the node passes all the filters.
	pub fn is_visible(&self, args: &Args) -> bool {
		if !args.typs.contains(&self.typ) {
			return false;
		}
		if self.conf.app_const.is_hidden(self.rel_importance(args)) {
			return false;
		}
		if let Some(exclude) = &args.exclude {
			if exclude.is_match(&self.name) {
				return false;
			}
		}
		if let Some(only) = &args.only {
			if !only.is_match(&self.name) {
				return false;
			}
		}
		true
	}

	/// The name of the node this node collapses into, if any.
	pub fn collapse_target(&self) -> Option<String> {
		match &self.collapse {
			Some(Collapse::Name(name)) => Some(name.clone()),
			Some(Collapse::Ext(ext)) => {
				let stem = Path::new(&self.name)
					.file_stem()
					.map(|s| s.to_string_lossy().into_owned())
					.unwrap_or_default();
				Some(format!("{stem}.{ext}"))
			}
			None => None,
		}
	}

	// ===== Rendering =====

	/// The combined style directives for the name of the node.
	fn directives(&self, args: &Args) -> String {
		let typ_style = self.conf.typ_info(self.typ).style;
		let imp_style = self
			.conf
			.app_const
			.imp_style(self.rel_importance(args))
			.unwrap_or("")
			.to_string();
		[typ_style, self.spec_style.clone(), imp_style]
			.into_iter()
			.filter(|s| !s.is_empty())
			.collect::<Vec<_>>()
			.join(" ")
	}

	/// The style directives for the icon, which cannot be italic or
	/// underlined.
	fn icon_directives(&self, args: &Args) -> String {
		self.directives(args)
			.split(' ')
			.filter(|w| !w.is_empty() && *w != "italic" && *w != "underline")
			.collect::<Vec<_>>()
			.join(" ")
	}

	/// The icon part of the name cell, including the trailing space.
	fn icon_markup(&self, args: &Args) -> String {
		if !args.icon {
			return String::new();
		}
		let icon = match &self.icon {
			Some(icon) if !icon.is_empty() => icon.clone(),
			_ => " ".to_string(),
		};
		wrap(&self.icon_directives(args), &format!("{icon} "))
	}

	/// The styled name of the node along with its suffix.
	fn styled_name(&self, args: &Args, aligned: bool) -> String {
		let directives = self.directives(args);
		let suffix = if args.suffix {
			self.conf.typ_info(self.typ).suffix
		} else {
			String::new()
		};
		if aligned {
			if let Some(rest) = self.name.strip_prefix('.') {
				return format!(
					"{}{}",
					wrap("dimmed", "."),
					wrap(&directives, &format!("{rest}{suffix}"))
				);
			}
			return format!(" {}", wrap(&directives, &format!("{}{suffix}", self.name)));
		}
		wrap(&directives, &format!("{}{suffix}", self.name))
	}

	/// Whether the name should be aligned to account for a leading dot.
	fn is_aligned(&self, args: &Args) -> bool {
		args.align && !self.is_arg
	}

	/// The cell shown in the grid view.
	pub fn grid_cell(&self, args: &Args) -> String {
		format!(
			"{}{}",
			self.icon_markup(args),
			self.styled_name(args, self.is_aligned(args))
		)
	}

	/// The name cell for the list and detail views, including the symlink
	/// target but excluding the tree prefix.
	pub fn name_cell(&self, args: &Args) -> String {
		let mut out = self.grid_cell(args);
		if args.sym && self.typ == Typ::Symlink {
			let target = SymTarget::resolve(&self.path, &self.conf);
			out.push(' ');
			out.push_str(&target.markup(&self.conf));
		}
		out
	}

	/// The markup for the given detail field.
	pub fn detail_cell(&self, field: DetailField, args: &Args) -> String {
		let conf = &self.conf;
		let ec = &conf.entry_const;
		match field {
			DetailField::Dev => wrap(&ec.dev_style, &self.meta.dev().to_string()),
			DetailField::Ino => wrap(&ec.ino_style, &self.meta.ino().to_string()),
			DetailField::Nlink => {
				let nlink = self.meta.nlink();
				let style = ec.nlink_styles.get(self.typ == Typ::Dir, nlink);
				wrap(style, &nlink.to_string())
			}
			DetailField::Typ => {
				let info = conf.typ_info(self.typ);
				wrap(&info.style, &info.ch)
			}
			DetailField::Perm => perm_markup(self.meta.permissions().mode(), conf),
			DetailField::Oct => oct_markup(self.meta.permissions().mode(), conf),
			DetailField::User => {
				let style = if self.meta.uid() == owner::current_uid() {
					&ec.user_styles.curr
				} else {
					&ec.user_styles.other
				};
				wrap(style, &self.user_name())
			}
			DetailField::Uid => {
				let style = if self.meta.uid() == owner::current_uid() {
					&ec.user_styles.curr
				} else {
					&ec.user_styles.other
				};
				wrap(style, &self.meta.uid().to_string())
			}
			DetailField::Group => {
				let style = if owner::current_user_in_group(self.meta.gid()) {
					&ec.group_styles.curr
				} else {
					&ec.group_styles.other
				};
				wrap(style, &self.group_name())
			}
			DetailField::Gid => {
				let style = if owner::current_user_in_group(self.meta.gid()) {
					&ec.group_styles.curr
				} else {
					&ec.group_styles.other
				};
				wrap(style, &self.meta.gid().to_string())
			}
			DetailField::Size => {
				if self.typ == Typ::Dir {
					String::new()
				} else {
					format_size(self.meta.size(), args.unit, &ec.size_styles)
				}
			}
			DetailField::Blocks => {
				if self.typ == Typ::Dir {
					String::new()
				} else {
					wrap(&ec.blocks_style, &self.meta.blocks().to_string())
				}
			}
			DetailField::Btime | DetailField::Ctime | DetailField::Mtime | DetailField::Atime => {
				match self.time(field) {
					Some(time) => format_time(time, conf.timestamp_format(field)),
					None => String::new(),
				}
			}
			DetailField::Git => String::new(),
			DetailField::Name => self.name_cell(args),
			_ => String::new(),
		}
	}
}
EOF
echo ok"}

