//! Arrangement of nodes into a tree based on their collapse rules.

use std::collections::HashMap;

use crate::models::Node;

/// Attach nodes to the nodes they collapse into, returning the roots.
///
/// A node whose chain of principals leads back to itself is kept at the top
/// level, as are nodes whose principal is not present.
pub fn build_tree(nodes: Vec<Node>) -> Vec<Node> {
	let index: HashMap<String, usize> = nodes
		.iter()
		.enumerate()
		.map(|(i, n)| (n.name.clone(), i))
		.collect();

	let mut parent_of: Vec<Option<usize>> = nodes
		.iter()
		.map(|node| {
			node.collapse_target()
				.filter(|target| *target != node.name)
				.and_then(|target| index.get(&target).copied())
		})
		.collect();

	// Break cycles by turning any node whose ancestry loops into a root.
	for i in 0..nodes.len() {
		let mut visited = vec![i];
		let mut cur = i;
		while let Some(p) = parent_of[cur] {
			if visited.contains(&p) {
				parent_of[i] = None;
				break;
			}
			visited.push(p);
			cur = p;
		}
	}

	let mut children: Vec<Vec<usize>> = vec![vec![]; nodes.len()];
	let mut roots: Vec<usize> = vec![];
	for (i, parent) in parent_of.iter().enumerate() {
		match parent {
			Some(p) => children[*p].push(i),
			None => roots.push(i),
		}
	}

	let mut slots: Vec<Option<Node>> = nodes.into_iter().map(Some).collect();
	roots
		.into_iter()
		.map(|i| take(i, &children, &mut slots))
		.collect()
}

fn take(i: usize, children: &[Vec<usize>], slots: &mut Vec<Option<Node>>) -> Node {
	let mut node = slots[i].take().expect("node taken twice");
	node.children = children[i]
		.iter()
		.map(|c| take(*c, children, slots))
		.collect();
	node
}

/// Flatten a tree into rows of `(prefix, node)` where the prefix is made of
/// the tree drawing shapes for the node's depth.
pub fn flatten<'a>(
	roots: &'a [Node],
	indent: &str,
	shapes: &crate::config::TreeInfo,
) -> Vec<(String, &'a Node)> {
	let mut rows = vec![];
	for root in roots {
		rows.push((String::new(), root));
		flatten_children(root, "", indent, shapes, &mut rows);
	}
	rows
}

fn flatten_children<'a>(
	parent: &'a Node,
	ancestry: &str,
	indent: &str,
	shapes: &crate::config::TreeInfo,
	rows: &mut Vec<(String, &'a Node)>,
) {
	let count = parent.children.len();
	for (i, child) in parent.children.iter().enumerate() {
		let is_last = i + 1 == count;
		let shape = if is_last {
			&shapes.bend_dash
		} else {
			&shapes.tee_dash
		};
		rows.push((format!("{ancestry}{indent}{shape}"), child));
		let continuation = if is_last {
			&shapes.space_space
		} else {
			&shapes.pipe_space
		};
		let child_ancestry = format!("{ancestry}{indent}{continuation}");
		flatten_children(child, &child_ancestry, indent, shapes, rows);
	}
}
