//! The list and detail views, which arrange nodes in a table.

use crate::args::Args;
use crate::config::Conf;
use crate::enums::DetailField;
use crate::fmt::{render, visible_len, wrap};
use crate::models::Node;
use crate::output::tree::flatten;

/// Render the given (possibly nested) nodes as lines of output.
pub fn render_table(roots: &[Node], args: &Args, conf: &Conf) -> Vec<String> {
	let indent = if args.align { "   " } else { "  " };
	let rows = flatten(roots, indent, &conf.app_const.tree);

	let mut columns: Vec<DetailField> = args.details.clone();
	columns.push(DetailField::Name);

	let mut table: Vec<Vec<String>> = vec![];
	if args.header && !args.details.is_empty() {
		table.push(columns.iter().map(|c| conf.column_name(*c)).collect());
	}
	for (prefix, node) in &rows {
		let cells = columns
			.iter()
			.map(|c| match c {
				DetailField::Name => format!("{prefix}{}", node.name_cell(args)),
				c => node.detail_cell(*c, args),
			})
			.collect();
		table.push(cells);
	}

	let widths: Vec<usize> = (0..columns.len())
		.map(|i| {
			table
				.iter()
				.map(|row| visible_len(&row[i]))
				.max()
				.unwrap_or(0)
		})
		.collect();

	let has_header = args.header && !args.details.is_empty();
	table
		.iter()
		.enumerate()
		.map(|(row_idx, row)| {
			let is_header = has_header && row_idx == 0;
			let mut line = String::new();
			for (i, cell) in row.iter().enumerate() {
				let is_last = i + 1 == row.len();
				let text = if is_last {
					cell.clone()
				} else {
					let padded = pad(cell, widths[i], columns[i].right_aligned());
					format!("{padded} ")
				};
				if is_header {
					line.push_str(&wrap(&conf.app_const.table.header_style, &text));
				} else {
					line.push_str(&text);
				}
			}
			render(&line)
		})
		.collect()
}

/// Pad a markup string to the given visible width.
fn pad(cell: &str, width: usize, right: bool) -> String {
	let len = visible_len(cell);
	let fill = " ".repeat(width.saturating_sub(len));
	if right {
		format!("{fill}{cell}")
	} else {
		format!("{cell}{fill}")
	}
}
