}

/// Pad a markup string to the given visible width.
fn pad(cell: &str, width: usize, right: bool) -> String {
	let len = visible_len(cell);
	let fill = " ".repeat(width.saturating_sub(len));
	if right {
		format!("{fill}{cell}")
	} else {
		format!("{cell}{fill}")
	}
}
