//! The grid view, which arranges node names in columns.

use crate::args::Args;
use crate::fmt::{render, visible_len};
use crate::models::Node;
use crate::utils::term::stdout_width;

const GAP: usize = 2;

/// Render the given nodes as a grid that fits the terminal.
pub fn render_grid(nodes: &[Node], args: &Args) -> Vec<String> {
	let cells: Vec<String> = nodes.iter().map(|n| n.grid_cell(args)).collect();
	if cells.is_empty() {
		return vec![];
	}
	let width = cells.iter().map(|c| visible_len(c)).max().unwrap_or(0);
	let term_width = stdout_width();

	let count = cells.len();
	let mut layout: Option<(usize, usize)> = None; // (rows, cols)
	if let Some(term_width) = term_width {
		for rows in 1..=count {
			let cols = count.div_ceil(rows);
			if cols * width + (cols - 1) * GAP <= term_width {
				layout = Some((rows, cols));
				break;
			}
		}
	}

	match layout {
		Some((rows, cols)) if cols > 1 => {
			let mut lines = vec![];
			for r in 0..rows {
				let mut parts = vec![];
				for c in 0..cols {
					let idx = if args.down { c * rows + r } else { r * cols + c };
					if let Some(cell) = cells.get(idx) {
						let fill = " ".repeat(width.saturating_sub(visible_len(cell)));
						parts.push(format!("{cell}{fill}"));
					}
				}
				lines.push(render(&parts.join(&" ".repeat(GAP))));
			}
			lines
		}
		_ => cells.iter().map(|c| render(c)).collect(),
	}
}
