			Err(e) => {
				print_node_error(&name, &e.to_string());
				continue;
			}
		};
		let node = Node::new(name, path.clone(), meta, Rc::new(conf), true);
		if is_dir {
			dirs.push(node);
		} else {
			files.push(node);
		}
	}

	let show_headers = args.paths.len() > 1;

	if !files.is_empty() {
		let conf = group_conf(&files);
		for line in render_nodes(files, &args, &conf, false) {
			println!("{line}");
		}
	}

	for dir in dirs {
		if show_headers {
			println!();
			println!("{}", render(&wrap("bold", &format!("{}:", dir.name))));
		}
		let entries = match std::fs::read_dir(&dir.path) {
			Ok(entries) => entries,
			Err(e) => {
				println!("{}", render(&format!("<bold red>error:</> {e}")));
				continue;
			}
		};
		let mut nodes: Vec<Node> = vec![];
		for entry in entries.flatten() {
			let name = entry.file_name().to_string_lossy().into_owned();
			let path = dir.path.join(entry.file_name());
			if let Ok(meta) = std::fs::symlink_metadata(&path) {
				nodes.push(Node::new(name, path, meta, dir.conf.clone(), false));
			}
		}
		nodes.retain(|node| node.is_visible(&args));
		sort_nodes(&mut nodes, &args);
		for line in render_nodes(nodes, &args, &dir.conf, true) {
			println!("{line}");
		}
	}
}

/// Print the error encountered while preparing a node given on the command
/// line.
fn print_node_error(name: &str, err: &str) {
	println!(
		"{}:\n\t{}",
		render(&wrap("bold", name)),
		render(&format!("<bold red>error:</> {err}"))
	);
}

/// Sort nodes using the configured sort bases, keeping the original order for
/// nodes that compare equal.
fn sort_nodes(nodes: &mut [Node], args: &Args) {
	nodes.sort_by(|a, b| {
		for base in &args.sort_bases {
			let ord = base.compare(a, b);
			if ord != std::cmp::Ordering::Equal {
				return ord;
			}
		}
		std::cmp::Ordering::Equal
	});
}

/// Render nodes either as a grid or as a table, collapsing dependent nodes
/// into their principals when requested.
fn render_nodes(nodes: Vec<Node>, args: &Args, conf: &Conf, allow_tree: bool) -> Vec<String> {
	if args.grid && args.details.is_empty() {
		return output::render_grid(&nodes, args);
	}
	let roots = if allow_tree && args.collapse {
		output::build_tree(nodes)
	} else {
		nodes
	};
	output::render_table(&roots, args, conf)
}

/// Determine the configuration used for the table listing the files given on
/// the command line, which is that of their closest common directory.
fn group_conf(files: &[Node]) -> Conf {
	let parents: Vec<PathBuf> = files
		.iter()
		.map(|f| absolute_parent(&f.path))
		.collect();
	let common = common_ancestor(&parents);
	match common {
		Some(dir) => load_conf(&dir, true).unwrap_or_else(|_| default_conf()),
		None => default_conf(),
	}
}

fn default_conf() -> Conf {
	load_conf(Path::new("/nonexistent-pls-default"), true).unwrap_or_default()
}

/// The absolute path of the directory containing the given path.
fn absolute_parent(path: &Path) -> PathBuf {
	let parent = match path.parent() {
		Some(p) if !p.as_os_str().is_empty() => p.to_path_buf(),
		_ => PathBuf::from("."),
	};
	std::fs::canonicalize(&parent).unwrap_or_else(|_| {
		if parent.is_absolute() {
			parent
		} else {
			std::env::current_dir()
				.map(|cwd| cwd.join(&parent))
				.unwrap_or(parent)
		}
	})
}

/// The longest common prefix of the given paths.
fn common_ancestor(paths: &[PathBuf]) -> Option<PathBuf> {
	let first = paths.first()?;
	let mut common: Vec<std::path::Component> = first.components().collect();
	for path in &paths[1..] {
		let comps: Vec<std::path::Component> = path.components().collect();
		let len = common
			.iter()
			.zip(comps.iter())
			.take_while(|(a, b)| a == b)
			.count();
		common.truncate(len);
	}
	if common.is_empty() {
		return None;
	}
	Some(common.iter().map(|c| c.as_os_str()).collect())
}
