//! Minimal detection of the terminal dimensions.
//!
//! The size is queried from standard output, standard error and standard
//! input, in that order, returning the first stream that is a terminal.

use std::mem::MaybeUninit;

/// The width of a terminal in columns.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Width(pub u16);

/// The height of a terminal in rows.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Height(pub u16);

/// Query the size of the terminal attached to the given file descriptor.
pub fn terminal_size_of(fd: libc::c_int) -> Option<(Width, Height)> {
	unsafe {
		if libc::isatty(fd) != 1 {
			return None;
		}
		let mut ws = MaybeUninit::<libc::winsize>::zeroed();
		if libc::ioctl(fd, libc::TIOCGWINSZ, ws.as_mut_ptr()) == -1 {
			return None;
		}
		let ws = ws.assume_init();
		if ws.ws_col == 0 || ws.ws_row == 0 {
			return None;
		}
		Some((Width(ws.ws_col), Height(ws.ws_row)))
	}
}

/// The size of the terminal the process is attached to, if any.
pub fn terminal_size() -> Option<(Width, Height)> {
	[libc::STDOUT_FILENO, libc::STDERR_FILENO, libc::STDIN_FILENO]
		.into_iter()
		.find_map(terminal_size_of)
}
