def simulate(content, hw, reset_mode, trim_mode, guard, seg_mode, carry_mode):
    # seg_mode: "lines" -> split_inclusive('\n'); "newline_segments" -> split at '\n' dropping newline to gaps
    state = {"lw": 0, "carry": None}
