    def do_wrap(words):
        if carry_mode == "once_none":
            if state["carry"] is None and words:
                state["carry"] = words[0] if words[0].strip() == "" else ""
        elif carry_mode == "always":
            if words:
                state["carry"] = words[0] if words[0].strip() == "" else ""
        elif carry_mode == "set_if_ws":
            if words and words[0].strip() == "":
                state["carry"] = words[0]
            elif state["carry"] is None:
                state["carry"] = ""
        first = True
        i = 0
        while i < len(words):
            word = words[i]; trimmed = word.rstrip(); ww = display_width(trimmed); delta = len(word) - len(trimmed)
