                    words[i-1] = words[i-1].rstrip(" ")
                state["lw"] = 0
                words.insert(i, "\n"); i += 1
                c = state["carry"]
                if c is not None and c != "":
                    words.insert(i, c); state["lw"] += len(c); i += 1
                if trim_mode == "cur":
                    words[i] = trimmed; delta = 0
            state["lw"] += ww + delta
            i += 1
        return "".join(words)
    if seg_mode == "lines":
