            if reset_mode == "per_line_lw" and idx > 0: state["lw"] = 0
            if reset_mode == "blank" and line.strip() == "": state["lw"] = 0; state["carry"] = None
            if reset_mode == "blank_lw" and line.strip() == "": state["lw"] = 0
            out.append(do_wrap(find_words(line)))
