//! Formatting of timestamps using a format description language where
//! components are written as `[name modifier:value ...]`, with backslash
//! escapes for literal brackets.

use std::time::{Duration, SystemTime, UNIX_EPOCH};

const MONTHS_SHORT: [&str; 12] = [
	"Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
];
const MONTHS_LONG: [&str; 12] = [
	"January",
	"February",
	"March",
	"April",
	"May",
	"June",
	"July",
	"August",
	"September",
	"October",
	"November",
	"December",
];
const WEEKDAYS_LONG: [&str; 7] = [
	"Monday",
	"Tuesday",
	"Wednesday",
	"Thursday",
	"Friday",
	"Saturday",
	"Sunday",
];
const WEEKDAYS_SHORT: [&str; 7] = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];

/// A broken down civil date and time.
#[derive(Debug, Clone, Copy)]
pub struct DateTime {
	pub year: i64,
	pub month: u32,
	pub day: u32,
	pub hour: u32,
	pub minute: u32,
	pub second: u32,
	pub nanos: u32,
	/// Day of the year, starting from 1.
	pub ordinal: u32,
	/// Day of the week, where Monday is 0.
	pub weekday: u32,
	/// The UTC offset in seconds.
	pub offset: i64,
	/// Seconds since the Unix epoch.
	pub unix: i64,
}

impl DateTime {
	/// Break down a system time in the local time zone.
	pub fn from_system_time(time: SystemTime) -> Self {
		let (secs, nanos) = match time.duration_since(UNIX_EPOCH) {
			Ok(d) => (d.as_secs() as i64, d.subsec_nanos()),
			Err(e) => {
				let d: Duration = e.duration();
				if d.subsec_nanos() == 0 {
					(-(d.as_secs() as i64), 0)
				} else {
					(-(d.as_secs() as i64) - 1, 1_000_000_000 - d.subsec_nanos())
				}
			}
		};
		let offset = local_offset(secs);
		let local = secs + offset;
		let days = local.div_euclid(86_400);
		let rem = local.rem_euclid(86_400);
		let (year, month, day) = civil_from_days(days);
		let ordinal = ordinal(year, month, day);
		// 1970-01-01 was a Thursday (index 3 with Monday as 0).
		let weekday = (days + 3).rem_euclid(7) as u32;
		Self {
			year,
			month,
			day,
			hour: (rem / 3600) as u32,
			minute: ((rem % 3600) / 60) as u32,
			second: (rem % 60) as u32,
			nanos,
			ordinal,
			weekday,
			offset,
			unix: secs,
		}
	}

	/// Days from Sunday (0) to Saturday (6).
	fn days_from_sunday(&self) -> u32 {
		(self.weekday + 1) % 7
	}

	/// The week number where weeks start on Sunday and the first Sunday of
	/// the year starts week 1.
	fn sunday_based_week(&self) -> u32 {
		(self.ordinal + 6 - self.days_from_sunday()) / 7
	}

	/// The week number where weeks start on Monday and the first Monday of
	/// the year starts week 1.
	fn monday_based_week(&self) -> u32 {
		(self.ordinal + 6 - self.weekday) / 7
	}

	/// The ISO 8601 week number.
	fn iso_week(&self) -> u32 {
		let week = (self.ordinal + 10 - (self.weekday + 1)) / 7;
		if week == 0 {
			weeks_in_year(self.year - 1)
		} else if week > weeks_in_year(self.year) {
			1
		} else {
			week
		}
	}
}

fn weeks_in_year(year: i64) -> u32 {
	// The weekday of January 1st and December 31st of the year.
	let jan1 = weekday_of(year, 1, 1);
	let dec31 = weekday_of(year, 12, 31);
	// A year has 53 ISO weeks when it starts or ends on a Thursday.
	if jan1 == 3 || dec31 == 3 {
		53
	} else {
		52
	}
}

/// The weekday (Monday = 0) of the given civil date.
fn weekday_of(year: i64, month: u32, day: u32) -> u32 {
	let days = days_from_civil(year, month, day);
	(days + 3).rem_euclid(7) as u32
}

/// Determine the local UTC offset (in seconds) for the given timestamp.
fn local_offset(secs: i64) -> i64 {
	unsafe {
		let t: libc::time_t = secs as libc::time_t;
		let mut tm: libc::tm = std::mem::zeroed();
		if libc::localtime_r(&t, &mut tm).is_null() {
			0
		} else {
			tm.tm_gmtoff as i64
		}
	}
}

/// Convert days since the Unix epoch into a civil date.
fn civil_from_days(z: i64) -> (i64, u32, u32) {
	let z = z + 719_468;
	let era = z.div_euclid(146_097);
	let doe = z.rem_euclid(146_097);
	let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
	let y = yoe + era * 400;
	let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
	let mp = (5 * doy + 2) / 153;
	let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
	let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
	(if m <= 2 { y + 1 } else { y }, m, d)
}

/// Convert a civil date into days since the Unix epoch.
fn days_from_civil(year: i64, month: u32, day: u32) -> i64 {
	let y = if month <= 2 { year - 1 } else { year };
	let era = y.div_euclid(400);
	let yoe = y.rem_euclid(400);
	let m = month as i64;
	let doy = (153 * (if m > 2 { m - 3 } else { m + 9 }) + 2) / 5 + day as i64 - 1;
	let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
	era * 146_097 + doe - 719_468
}

fn is_leap(year: i64) -> bool {
	(year % 4 == 0 && year % 100 != 0) || year % 400 == 0
}

fn ordinal(year: i64, month: u32, day: u32) -> u32 {
	const CUMULATIVE: [u32; 12] = [0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334];
	let mut ord = CUMULATIVE[(month - 1) as usize] + day;
	if month > 2 && is_leap(year) {
		ord += 1;
	}
	ord
}

/// Errors that can occur while parsing a format description.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum InvalidFormatDescription {
	UnclosedOpeningBracket { index: usize },
	InvalidComponentName { name: String, index: usize },
	InvalidModifier { value: String, index: usize },
	Expected { what: &'static str, index: usize },
	MissingComponentName { index: usize },
	MissingRequiredModifier { name: &'static str, index: usize },
	NotSupported {
		what: &'static str,
		context: &'static str,
		index: usize,
	},
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Padding {
	Zero,
	Space,
	None,
}

/// A parsed component with its modifiers resolved.
#[derive(Debug, Clone, PartialEq, Eq)]
enum Component {
	Year {
		repr: YearRepr,
		padding: Padding,
		sign_mandatory: bool,
	},
	Month {
		repr: MonthRepr,
		padding: Padding,
	},
	Day {
		padding: Padding,
	},
	Ordinal {
		padding: Padding,
	},
	Weekday {
		repr: WeekdayRepr,
		one_indexed: bool,
	},
	WeekNumber {
		repr: WeekNumberRepr,
		padding: Padding,
	},
	Hour {
		twelve: bool,
		padding: Padding,
	},
	Minute {
		padding: Padding,
	},
	Second {
		padding: Padding,
	},
	Subsecond {
		digits: Option<u8>,
	},
	Period {
		upper: bool,
	},
	OffsetHour {
		sign_mandatory: bool,
		padding: Padding,
	},
	OffsetMinute {
		padding: Padding,
	},
	OffsetSecond {
		padding: Padding,
	},
	UnixTimestamp {
		precision: Precision,
		sign_mandatory: bool,
	},
	Ignore,
	End,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum YearRepr {
	Full,
	LastTwo,
	Century,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum MonthRepr {
	Numerical,
	Short,
	Long,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum WeekdayRepr {
	Long,
	Short,
	Sunday,
	Monday,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum WeekNumberRepr {
	Iso,
	Sunday,
	Monday,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Precision {
	Second,
	Millisecond,
	Microsecond,
	Nanosecond,
}

/// An item of a parsed format description.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Item {
	Literal(String),
	Component(Component),
}

/// A modifier as written in the description, with the position of its key
/// and value.
struct Modifier<'a> {
	key: &'a str,
	key_index: usize,
	value: &'a str,
	value_index: usize,
}

/// Parse a format description into items.
pub fn parse_description(input: &str) -> Result<Vec<Item>, InvalidFormatDescription> {
	let bytes = input.as_bytes();
	let mut items = vec![];
	let mut literal = String::new();
	let mut i = 0;
	while i < bytes.len() {
		match bytes[i] {
			b'\\' => match bytes.get(i + 1) {
				Some(c @ (b'\\' | b'[' | b']')) => {
					literal.push(*c as char);
					i += 2;
				}
				Some(_) => {
					return Err(InvalidFormatDescription::Expected {
						what: "valid escape sequence",
						index: i + 1,
					})
				}
				None => {
					return Err(InvalidFormatDescription::Expected {
						what: "valid escape sequence",
						index: i,
					})
				}
			},
			b'[' => {
				if !literal.is_empty() {
					items.push(Item::Literal(std::mem::take(&mut literal)));
				}
				let (component, next) = parse_component(input, i)?;
				if let Some(component) = component {
					items.push(Item::Component(component));
				}
				i = next;
			}
			_ => {
				// Copy a whole character, which may span several bytes.
				let ch = input[i..].chars().next().unwrap_or(' ');
				literal.push(ch);
				i += ch.len_utf8();
			}
		}
	}
	if !literal.is_empty() {
		items.push(Item::Literal(literal));
	}
	Ok(items)
}

fn is_ws(b: u8) -> bool {
	b.is_ascii_whitespace()
}

/// Parse the component starting with the opening bracket at `open`, returning
/// the component and the index just past the closing bracket.
fn parse_component(
	input: &str,
	open: usize,
) -> Result<(Option<Component>, usize), InvalidFormatDescription> {
	let bytes = input.as_bytes();
	let mut i = open + 1;

	// Leading whitespace.
	let ws_start = i;
	while i < bytes.len() && is_ws(bytes[i]) {
		i += 1;
	}
	let leading_ws = if i > ws_start { Some(ws_start) } else { None };

	// The component name runs until whitespace or a bracket.
	let name_start = i;
	while i < bytes.len() && !is_ws(bytes[i]) && bytes[i] != b'[' && bytes[i] != b']' {
		i += 1;
	}
	if i == name_start {
		return Err(InvalidFormatDescription::MissingComponentName {
			index: leading_ws.unwrap_or(open),
		});
	}
	let name = &input[name_start..i];

	if name == "optional" {
		return Err(InvalidFormatDescription::NotSupported {
			what: "optional item",
			context: "runtime-parsed format descriptions",
			index: open,
		});
	}
	if name == "first" {
		return Err(InvalidFormatDescription::NotSupported {
			what: "'first' item",
			context: "runtime-parsed format descriptions",
			index: open,
		});
	}

	// Modifiers, each preceded by whitespace.
	let mut modifiers: Vec<Modifier> = vec![];
	loop {
		let ws_start = i;
		while i < bytes.len() && is_ws(bytes[i]) {
			i += 1;
		}
		if i == ws_start {
			break;
		}
		let tok_start = i;
		while i < bytes.len() && !is_ws(bytes[i]) && bytes[i] != b'[' && bytes[i] != b']' {
			i += 1;
		}
		if i == tok_start {
			break;
		}
		let token = &input[tok_start..i];
		match token.find(':') {
			Some(colon) => modifiers.push(Modifier {
				key: &token[..colon],
				key_index: tok_start,
				value: &token[colon + 1..],
				value_index: tok_start + colon + 1,
			}),
			None => {
				return Err(InvalidFormatDescription::InvalidModifier {
					value: token.to_string(),
					index: tok_start,
				})
			}
		}
	}

	if i >= bytes.len() || bytes[i] != b']' {
		return Err(InvalidFormatDescription::UnclosedOpeningBracket { index: open });
	}
	let component = build_component(name, name_start, &modifiers)?;
	Ok((component, i + 1))
}

fn invalid_modifier(value: &str, index: usize) -> InvalidFormatDescription {
	InvalidFormatDescription::InvalidModifier {
		value: value.to_string(),
		index,
	}
}

fn parse_padding(m: &Modifier) -> Result<Padding, InvalidFormatDescription> {
	match m.value {
		"space" => Ok(Padding::Space),
		"zero" => Ok(Padding::Zero),
		"none" => Ok(Padding::None),
		v => Err(invalid_modifier(v, m.value_index)),
	}
}

fn parse_bool(m: &Modifier) -> Result<bool, InvalidFormatDescription> {
	match m.value {
		"true" => Ok(true),
		"false" => Ok(false),
		v => Err(invalid_modifier(v, m.value_index)),
	}
}

fn parse_sign(m: &Modifier) -> Result<bool, InvalidFormatDescription> {
	match m.value {
		"automatic" => Ok(false),
		"mandatory" => Ok(true),
		v => Err(invalid_modifier(v, m.value_index)),
	}
}

/// Resolve a component name and its modifiers into a component.
fn build_component(
	name: &str,
	name_index: usize,
	modifiers: &[Modifier],
) -> Result<Option<Component>, InvalidFormatDescription> {
	macro_rules! unknown_key {
		($m:expr) => {
			return Err(invalid_modifier($m.key, $m.key_index))
		};
	}
	let component = match name {
		"year" => {
			let mut repr = YearRepr::Full;
			let mut padding = Padding::Zero;
			let mut sign_mandatory = false;
			for m in modifiers {
				match m.key {
					"repr" => {
						repr = match m.value {
							"full" => YearRepr::Full,
							"last_two" => YearRepr::LastTwo,
							"century" => YearRepr::Century,
							v => return Err(invalid_modifier(v, m.value_index)),
						}
					}
					"padding" => padding = parse_padding(m)?,
					"sign" => sign_mandatory = parse_sign(m)?,
					"range" => match m.value {
						"extended" | "standard" => {}
						v => return Err(invalid_modifier(v, m.value_index)),
					},
					"base" => match m.value {
						"calendar" | "iso_week" => {}
						v => return Err(invalid_modifier(v, m.value_index)),
					},
					_ => unknown_key!(m),
				}
			}
			Component::Year {
				repr,
				padding,
				sign_mandatory,
			}
		}
		"month" => {
			let mut repr = MonthRepr::Numerical;
			let mut padding = Padding::Zero;
			for m in modifiers {
				match m.key {
					"repr" => {
						repr = match m.value {
							"numerical" => MonthRepr::Numerical,
							"short" => MonthRepr::Short,
							"long" => MonthRepr::Long,
							v => return Err(invalid_modifier(v, m.value_index)),
						}
					}
					"padding" => padding = parse_padding(m)?,
					"case_sensitive" => {
						parse_bool(m)?;
					}
					_ => unknown_key!(m),
				}
			}
			Component::Month { repr, padding }
		}
		"day" | "ordinal" | "minute" | "second" | "offset_minute" | "offset_second" => {
			let mut padding = Padding::Zero;
			for m in modifiers {
				match m.key {
					"padding" => padding = parse_padding(m)?,
					_ => unknown_key!(m),
				}
			}
			match name {
				"day" => Component::Day { padding },
				"ordinal" => Component::Ordinal { padding },
				"minute" => Component::Minute { padding },
				"second" => Component::Second { padding },
				"offset_minute" => Component::OffsetMinute { padding },
				_ => Component::OffsetSecond { padding },
			}
		}
		"weekday" => {
			let mut repr = WeekdayRepr::Long;
			let mut one_indexed = true;
			for m in modifiers {
				match m.key {
					"repr" => {
						repr = match m.value {
							"long" => WeekdayRepr::Long,
							"short" => WeekdayRepr::Short,
							"sunday" => WeekdayRepr::Sunday,
							"monday" => WeekdayRepr::Monday,
							v => return Err(invalid_modifier(v, m.value_index)),
						}
					}
					"one_indexed" => one_indexed = parse_bool(m)?,
					"case_sensitive" => {
						parse_bool(m)?;
					}
					_ => unknown_key!(m),
				}
			}
			Component::Weekday { repr, one_indexed }
		}
		"week_number" => {
			let mut repr = WeekNumberRepr::Iso;
			let mut padding = Padding::Zero;
			for m in modifiers {
				match m.key {
					"repr" => {
						repr = match m.value {
							"iso" => WeekNumberRepr::Iso,
							"sunday" => WeekNumberRepr::Sunday,
							"monday" => WeekNumberRepr::Monday,
							v => return Err(invalid_modifier(v, m.value_index)),
						}
					}
					"padding" => padding = parse_padding(m)?,
					_ => unknown_key!(m),
				}
			}
			Component::WeekNumber { repr, padding }
		}
		"hour" => {
			let mut twelve = false;
			let mut padding = Padding::Zero;
			for m in modifiers {
				match m.key {
					"repr" => {
						twelve = match m.value {
							"24" => false,
							"12" => true,
							v => return Err(invalid_modifier(v, m.value_index)),
						}
					}
					"padding" => padding = parse_padding(m)?,
					_ => unknown_key!(m),
				}
			}
			Component::Hour { twelve, padding }
		}
		"subsecond" => {
			let mut digits = None;
			for m in modifiers {
				match m.key {
					"digits" => {
						digits = match m.value {
							"1+" => None,
							"1" => Some(1),
							"2" => Some(2),
							"3" => Some(3),
							"4" => Some(4),
							"5" => Some(5),
							"6" => Some(6),
							"7" => Some(7),
							"8" => Some(8),
							"9" => Some(9),
							v => return Err(invalid_modifier(v, m.value_index)),
						}
					}
					_ => unknown_key!(m),
				}
			}
			Component::Subsecond { digits }
		}
		"period" => {
			let mut upper = true;
			for m in modifiers {
				match m.key {
					"case" => {
						upper = match m.value {
							"upper" => true,
							"lower" => false,
							v => return Err(invalid_modifier(v, m.value_index)),
						}
					}
					"case_sensitive" => {
						parse_bool(m)?;
					}
					_ => unknown_key!(m),
				}
			}
			Component::Period { upper }
		}
		"offset_hour" => {
			let mut sign_mandatory = false;
			let mut padding = Padding::Zero;
			for m in modifiers {
				match m.key {
					"sign" => sign_mandatory = parse_sign(m)?,
					"padding" => padding = parse_padding(m)?,
					_ => unknown_key!(m),
				}
			}
			Component::OffsetHour {
				sign_mandatory,
				padding,
			}
		}
		"unix_timestamp" => {
			let mut precision = Precision::Second;
			let mut sign_mandatory = false;
			for m in modifiers {
				match m.key {
					"precision" => {
						precision = match m.value {
							"second" => Precision::Second,
							"millisecond" => Precision::Millisecond,
							"microsecond" => Precision::Microsecond,
							"nanosecond" => Precision::Nanosecond,
							v => return Err(invalid_modifier(v, m.value_index)),
						}
					}
					"sign" => sign_mandatory = parse_sign(m)?,
					_ => unknown_key!(m),
				}
			}
			Component::UnixTimestamp {
				precision,
				sign_mandatory,
			}
		}
		"ignore" => {
			let mut count = None;
			for m in modifiers {
				match m.key {
					"count" => {
						count = match m.value.parse::<usize>() {
							Ok(n) if n > 0 => Some(n),
							_ => return Err(invalid_modifier(m.value, m.value_index)),
						}
					}
					_ => unknown_key!(m),
				}
			}
			if count.is_none() {
				return Err(InvalidFormatDescription::MissingRequiredModifier {
					name: "count",
					index: name_index,
				});
			}
			Component::Ignore
		}
		"end" => {
			if let Some(m) = modifiers.first() {
				unknown_key!(m);
			}
			Component::End
		}
		_ => {
			return Err(InvalidFormatDescription::InvalidComponentName {
				name: name.to_string(),
				index: name_index,
			})
		}
	};
	Ok(Some(component))
}

fn pad(value: impl std::fmt::Display, width: usize, padding: Padding) -> String {
	let s = value.to_string();
	match padding {
		Padding::Zero => format!("{s:0>width$}"),
		Padding::Space => format!("{s:>width$}"),
		Padding::None => s,
	}
}

/// Format a signed number with the given padding, placing the sign before the
/// padding.
fn pad_signed(value: i64, width: usize, padding: Padding, sign_mandatory: bool) -> String {
	let digits = pad(value.abs(), width, padding);
	if value < 0 {
		format!("-{digits}")
	} else if sign_mandatory {
		format!("+{digits}")
	} else {
		digits
	}
}

fn format_component(component: &Component, dt: &DateTime) -> String {
	match component {
		Component::Year {
			repr,
			padding,
			sign_mandatory,
		} => match repr {
			YearRepr::Full => {
				let width = if dt.year.abs() >= 100_000 {
					6
				} else if dt.year.abs() >= 10_000 {
					5
				} else {
					4
				};
				pad_signed(dt.year, width, *padding, *sign_mandatory || dt.year >= 10_000)
			}
			YearRepr::LastTwo => pad(dt.year.rem_euclid(100), 2, *padding),
			YearRepr::Century => {
				let century = dt.year / 100;
				let width = if century.abs() >= 1000 {
					4
				} else if century.abs() >= 100 {
					3
				} else {
					2
				};
				pad_signed(century, width, *padding, *sign_mandatory)
			}
		},
		Component::Month { repr, padding } => match repr {
			MonthRepr::Numerical => pad(dt.month, 2, *padding),
			MonthRepr::Short => MONTHS_SHORT[(dt.month - 1) as usize].to_string(),
			MonthRepr::Long => MONTHS_LONG[(dt.month - 1) as usize].to_string(),
		},
		Component::Day { padding } => pad(dt.day, 2, *padding),
		Component::Ordinal { padding } => pad(dt.ordinal, 3, *padding),
		Component::Weekday { repr, one_indexed } => match repr {
			WeekdayRepr::Long => WEEKDAYS_LONG[dt.weekday as usize].to_string(),
			WeekdayRepr::Short => WEEKDAYS_SHORT[dt.weekday as usize].to_string(),
			WeekdayRepr::Sunday => (dt.days_from_sunday() + *one_indexed as u32).to_string(),
			WeekdayRepr::Monday => (dt.weekday + *one_indexed as u32).to_string(),
		},
		Component::WeekNumber { repr, padding } => {
			let week = match repr {
				WeekNumberRepr::Iso => dt.iso_week(),
				WeekNumberRepr::Sunday => dt.sunday_based_week(),
				WeekNumberRepr::Monday => dt.monday_based_week(),
			};
			pad(week, 2, *padding)
		}
		Component::Hour { twelve, padding } => {
			let hour = if *twelve {
				match dt.hour % 12 {
					0 => 12,
					h => h,
				}
			} else {
				dt.hour
			};
			pad(hour, 2, *padding)
		}
		Component::Minute { padding } => pad(dt.minute, 2, *padding),
		Component::Second { padding } => pad(dt.second, 2, *padding),
		Component::Subsecond { digits } => {
			let nanos = format!("{:09}", dt.nanos);
			match digits {
				Some(d) => nanos[..*d as usize].to_string(),
				None => {
					let trimmed = nanos.trim_end_matches('0');
					if trimmed.is_empty() {
						"0".to_string()
					} else {
						trimmed.to_string()
					}
				}
			}
		}
		Component::Period { upper } => {
			let p = if dt.hour < 12 { "AM" } else { "PM" };
			if *upper {
				p.to_string()
			} else {
				p.to_lowercase()
			}
		}
		Component::OffsetHour {
			sign_mandatory,
			padding,
		} => {
			let hours = dt.offset / 3600;
			let digits = pad(hours.abs(), 2, *padding);
			if dt.offset < 0 {
				format!("-{digits}")
			} else if *sign_mandatory {
				format!("+{digits}")
			} else {
				digits
			}
		}
		Component::OffsetMinute { padding } => pad(((dt.offset % 3600) / 60).abs(), 2, *padding),
		Component::OffsetSecond { padding } => pad((dt.offset % 60).abs(), 2, *padding),
		Component::UnixTimestamp {
			precision,
			sign_mandatory,
		} => {
			let value: i128 = match precision {
				Precision::Second => dt.unix as i128,
				Precision::Millisecond => dt.unix as i128 * 1_000 + dt.nanos as i128 / 1_000_000,
				Precision::Microsecond => dt.unix as i128 * 1_000_000 + dt.nanos as i128 / 1_000,
				Precision::Nanosecond => dt.unix as i128 * 1_000_000_000 + dt.nanos as i128,
			};
			if *sign_mandatory && value >= 0 {
				format!("+{value}")
			} else {
				value.to_string()
			}
		}
		Component::Ignore | Component::End => String::new(),
	}
}

/// Format a timestamp according to the given parsed description.
pub fn format_time(time: SystemTime, items: &[Item]) -> String {
	let dt = DateTime::from_system_time(time);
	let mut out = String::new();
	for item in items {
		match item {
			Item::Literal(text) => out.push_str(text),
			Item::Component(component) => out.push_str(&format_component(component, &dt)),
		}
	}
	out
}
