use std::cmp::Ordering;

#[derive(Clone, Debug)]
struct E { name: &'static str, btime: Option<u64> }

fn main() {
    let input = vec![
        ("core", Some(2)), ("stderr", Some(2)), ("stdout", Some(2)), ("stdin", Some(2)), ("fd", Some(2)),
        ("ptmx", Some(2)), ("urandom", Some(2)), ("zero", Some(2)), ("tty", Some(2)), ("full", Some(2)),
        ("random", Some(2)), ("null", Some(2)), ("shm", Some(1)), ("mqueue", None), ("pts", None),
    ];
    let entries: Vec<E> = input.iter().map(|(n, b)| E { name: n, btime: *b }).collect();
    type Cmp = fn(&Option<u64>, &Option<u64>) -> Ordering;
    let variants: Vec<(&str, Cmp)> = vec![
        ("equal", |a, b| match (a, b) { (Some(x), Some(y)) => x.cmp(y), _ => Ordering::Equal }),
        ("option", |a, b| a.cmp(b)),
        ("less", |a, b| match (a, b) { (Some(x), Some(y)) => x.cmp(y), _ => Ordering::Less }),
        ("greater", |a, b| match (a, b) { (Some(x), Some(y)) => x.cmp(y), _ => Ordering::Greater }),
        ("none_less_some_greater", |a, b| match (a, b) { (Some(x), Some(y)) => x.cmp(y), (None, Some(_)) => Ordering::Less, (Some(_), None) => Ordering::Greater, _ => Ordering::Equal }),
        ("zero", |a, b| a.unwrap_or(0).cmp(&b.unwrap_or(0))),
        ("max", |a, b| a.unwrap_or(u64::MAX).cmp(&b.unwrap_or(u64::MAX))),
    ];
    for (name, cmp) in &variants {
        let mut v = entries.clone();
        v.sort_by(|a, b| cmp(&a.btime, &b.btime));
        let s1: Vec<&str> = v.iter().map(|e| e.name).collect();
        let mut v = entries.clone();
        v.sort_by(|a, b| cmp(&a.btime, &b.btime).then_with(|| a.name.cmp(b.name)));
        let s2: Vec<&str> = v.iter().map(|e| e.name).collect();
        let mut v = entries.clone();
        v.sort_by(|a, b| cmp(&a.btime, &b.btime).reverse());
        let s3: Vec<&str> = v.iter().map(|e| e.name).collect();
        println!("{name}:\n  btime: {}\n  btime,name: {}\n  btime_: {}", s1.join(" "), s2.join(" "), s3.join(" "));
    }
}
